import{c as e,Q as o,j as r,m as a}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Claude Code 一年 GA 回顧：Auto Mode、Routine、手機編程的真實使用心得","description":"","frontmatter":{"url":"https://x.com/bcherny/status/2064034799711588805","title":"Claude Code 一年 GA 回顧：Auto Mode、Routine、手機編程的真實使用心得","author":"Boris Cherny","archived":"2026-06-15T00:00:00.000Z","category":"deep-application","handle":"@bcherny","published":"2026-06-08T00:00:00.000Z","score":"7.6/10","stats":"2205❤ · 122 retweets · 1519 bookmarks · 356804 views","tags":["claude-code","auto-mode","routines","loop-engineering","one-year-review","anthropic"],"type":"tweet-thread"},"headers":[],"relativePath":"research/tweets/2026-06-08-@bcherny-588805.md","filePath":"research/tweets/2026-06-08-@bcherny-588805.md","lastUpdated":1785909234000}'),d={name:"research/tweets/2026-06-08-@bcherny-588805.md"};function n(s,t,i,u,h,l){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="claude-code-一年-ga-回顧-auto-mode、routine、手機編程-—-bcherny" tabindex="-1">Claude Code 一年 GA 回顧：Auto Mode、Routine、手機編程 — @bcherny <a class="header-anchor" href="#claude-code-一年-ga-回顧-auto-mode、routine、手機編程-—-bcherny" aria-label="Permalink to &quot;Claude Code 一年 GA 回顧：Auto Mode、Routine、手機編程 — @bcherny&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/bcherny/status/2064034799711588805" target="_blank" rel="noreferrer">https://x.com/bcherny/status/2064034799711588805</a><strong>類別</strong>：deep-application <strong>統計</strong>：2205❤ · 122 retweets · 1519 bookmarks · 356804 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>When we first demoed Claude Code internally, it got two reactions on Slack.</p><p>A year after GA, @_catwu and I sat down to talk about what&#39;s changed: why I use auto mode instead of plan mode, how routines fix bugs before I see them, why I do most of my coding from my phone now, and where the product is going</p><hr><h2 id="核心內容-youtube-影片摘要" tabindex="-1">核心內容（YouTube 影片摘要） <a class="header-anchor" href="#核心內容-youtube-影片摘要" aria-label="Permalink to &quot;核心內容（YouTube 影片摘要）&quot;">​</a></h2><p>Claude Code 負責人 Boris Cherny 與 Cat Wu 一年回顧的核心論點：</p><ol><li><strong>Auto Mode 取代 Plan Mode</strong>：不再手動規劃步驟，讓 Claude 自主決定執行策略</li><li><strong>Routines 自動修 Bug</strong>：工作流自動在用戶看到問題前就完成修復</li><li><strong>手機編程</strong>：90% 的工作從手機完成，Claude Code 降低了環境門檻</li><li><strong>Loop Engineering 範式</strong>：不再直接 prompt，而是設計讓 agent 自行驅動的 loop</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8/10</td><td>Auto mode 和 Routine 均可直接啟用，Loop Engineering 範式立即可採納</td></tr><tr><td>B. 創新性 (20%)</td><td>8/10</td><td>Loop Engineering 範式轉移的早期定義，創始人視角具權威性</td></tr><tr><td>C. 證據品質 (20%)</td><td>6/10</td><td>YouTube 影片摘要，缺乏具體量化數據</td></tr><tr><td>D. 技術深度 (15%)</td><td>8/10</td><td>設計哲學層級的深度，Auto mode vs plan mode 決策有洞察</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>適用所有 Claude Code 用戶，範式轉移影響廣泛</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.6/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：Loop Engineering 範式適合整合進 CLAUDE.md 或 core rules 作為 agentic 工作哲學指引。</p>',14)])])}const p=e(d,[["render",n]]);export{g as __pageData,p as default};
